import json
with open('/app/resources/treasury_bulletin_1956_03.json') as f:
    data = json.load(f)

# Search for any numeric value that might be exchange rate
def find_all_text(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if isinstance(value, str) and ('rate' in key.lower() or 'exchange' in key.lower() or 'rupee' in key.lower()):
                results.append(f'{key}: {value}')
            results.extend(find_all_text(value, f'{path}.{key}'))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_all_text(item, f'{path}[{i}]'))
    return results

results = find_all_text(data)
for r in results:
    print(r)
